-- =============================================================================
-- 546 — LE CAHIER D'EXERCICES DE 1RE (partie 34)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 546 --niveau 1re --fichiers si.n1,si.n2 --suffixe 34 > supabase/contenu/546_exercices_1re_34.sql
--
-- 54 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   si.n1                   27 exercices · 9 chapitres
--   si.n2                   27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('0d25e817-4458-553c-8e2c-b24b74ce1e3e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le portail qui s’ouvre tout seul","competence":"observer-schema","situation":"Lola observe le portail automatique de son lycée : un bouton, une cellule sur le côté, un voyant orange, un moteur dans un coffret. Elle veut savoir qui fait quoi dans ce système.","documents":[{"id":"composants","type":"tableau","titre":"Les composants du portail","colonnes":["Repère","Composant"],"lignes":[["1","Batterie 24 V"],["2","Carte de puissance (variateur)"],["3","Moteur à courant continu"],["4","Réducteur à engrenages"],["5","Vantail du portail"]],"source":"Système imaginé pour l’exercice"},{"id":"info","type":"chaine","disposition":"ligne","titre":"Un chemin de l’information","noeuds":[{"id":"z1","texte":"Cellule photoélectrique"},{"id":"z2","texte":"Microcontrôleur"},{"id":"z3","texte":"Voyant orange"}],"liens":[{"de":"z1","a":"z2","texte":"présence"},{"de":"z2","a":"z3","texte":"ordre"}]}],"questions":[{"enonce":"Touche le composant qui acquiert l’information « un obstacle est présent ».","aide":"Acquérir, c’est mesurer une grandeur du monde réel : quel composant « regarde » devant le portail ?","type":"zone","document":"info","multiple":false},{"enonce":"Associe chaque composant du tableau à sa fonction dans la chaîne d’énergie.","aide":"Le moteur transforme l’énergie électrique en énergie mécanique : quel verbe de la chaîne cela donne-t-il ?","type":"association","gauche":[{"id":"g0","texte":"Batterie 24 V"},{"id":"g1","texte":"Carte de puissance (variateur)"},{"id":"g2","texte":"Moteur à courant continu"},{"id":"g3","texte":"Réducteur à engrenages"}],"droite":[{"id":"d0","texte":"Alimenter"},{"id":"d1","texte":"Convertir"},{"id":"d2","texte":"Distribuer"},{"id":"d3","texte":"Transmettre"}]},{"enonce":"Range chaque composant dans sa chaîne.","aide":"La chaîne d’information décide, la chaîne d’énergie exécute.","type":"categories","categories":[{"id":"c0","texte":"Chaîne d’information"},{"id":"c1","texte":"Chaîne d’énergie"}],"items":[{"id":"i0","texte":"Voyant orange"},{"id":"i1","texte":"Cellule photoélectrique"},{"id":"i2","texte":"Moteur"},{"id":"i3","texte":"Batterie 24 V"},{"id":"i4","texte":"Microcontrôleur"},{"id":"i5","texte":"Réducteur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La **cellule photoélectrique** est un capteur : elle réalise « acquérir ». Le microcontrôleur traite, le voyant communique."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"Chaîne d’énergie : la **batterie alimente**, la carte de puissance **distribue**, le moteur **convertit**, le réducteur **transmet** et le vantail est l’élément qui agit."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Capteur, microcontrôleur et voyant **décident et informent** ; batterie, moteur et réducteur **fournissent et transmettent la puissance**."}]$ex$::jsonb),
  ('0d25e817-4458-553c-8e2c-b24b74ce1e3e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le cahier des charges du vélo à assistance électrique","competence":"analyser-document","situation":"Une équipe de lycéens conçoit un vélo à assistance électrique. Leur cahier des charges exprime le besoin en fonctions de service ; chacune est assortie d’un critère, d’un niveau et d’une flexibilité.","documents":[{"id":"cdc","type":"tableau","titre":"Extrait du cahier des charges","colonnes":["Fonction de service","Critère","Niveau","Flexibilité"],"lignes":[["Aider le cycliste dans une côte","Puissance d’assistance","250 W","± 10 %"],["Permettre un long trajet sans recharge","Autonomie","60 km","± 5 km"],["Respecter la réglementation","Vitesse maximale assistée","25 km/h","aucune"],["Se recharger à la maison","Durée de recharge","5 h","+ 1 h"]],"source":"Cahier des charges imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la case qui donne le niveau attendu pour l’autonomie.","aide":"Le niveau est la valeur chiffrée attendue ; repère d’abord la ligne « Autonomie ».","type":"zone","document":"cdc","multiple":false},{"enonce":"Quelle est l’autonomie minimale acceptée par le cahier des charges ?","aide":"La flexibilité est la tolérance admise autour du niveau : niveau − tolérance.","type":"nombre","unite":"km"},{"enonce":"Un essai donne une autonomie de 52 km. L’exigence est-elle respectée ?","aide":"Calcule d’abord l’intervalle admis, puis place 52 km dedans ou dehors.","type":"choix","options":[{"id":"a","texte":"Non : 52 km est en dessous du minimum de 55 km"},{"id":"b","texte":"On ne peut pas conclure : il manque la flexibilité"},{"id":"c","texte":"Oui : un essai réel n’a pas à respecter le cahier des charges"},{"id":"d","texte":"Oui : 52 km reste dans la tolérance de ± 5 km autour de 60 km"}],"multiple":false},{"enonce":"Quelle puissance d’assistance minimale le vélo doit-il fournir dans une côte ?","aide":"Une flexibilité en pourcentage s’applique au niveau : 10 % de 250 W, à retrancher.","type":"nombre","unite":"W"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Le niveau de l’autonomie est **60 km**. Le critère dit sur quoi on mesure, le niveau dit quelle valeur on attend."},{"cle":{"type":"nombre","valeur":55,"tolerance":0},"affichage":"55 km","explication":"Niveau 60 km, flexibilité ± 5 km : l’autonomie acceptée va de 55 à 65 km, donc le minimum est 60 − 5 = **55 km**."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’intervalle admis est 55–65 km et 52 km est dehors : l’exigence n’est **pas respectée**. Comparer le réel au cahier des charges, c’est l’écart 3."},{"cle":{"type":"nombre","valeur":225,"tolerance":0},"affichage":"225 W","explication":"10 % de 250 W font 25 W : la puissance minimale est 250 − 25 = **225 W**."}]$ex$::jsonb),
  ('0d25e817-4458-553c-8e2c-b24b74ce1e3e'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Trois écarts pour un robot tondeuse","competence":"raisonner","situation":"Une équipe teste un robot tondeuse. Elle a un cahier des charges, une simulation et un prototype réel ; les trois ne racontent pas la même histoire. Il faut comprendre pourquoi.","documents":[{"id":"mesures","type":"tableau","titre":"Comparaison des trois sources","colonnes":["Grandeur","Cahier des charges","Simulation","Essai réel"],"lignes":[["Autonomie","≥ 2,0 h","2,6 h","1,7 h"],["Vitesse d’avance","≥ 0,5 m/s","0,6 m/s","0,58 m/s"]],"enteteLignes":true,"source":"Mesures imaginées pour l’exercice"},{"id":"notes","type":"texte","genre":"article","titre":"Notes de l’équipe","blocs":["Les instruments de mesure ont été étalonnés avant l’essai. La batterie et le moteur sont conformes à leur fiche technique.","L’essai s’est déroulé sur une pelouse plane, comme dans la simulation.","Le modèle numérique supposait que l’herbe n’oppose aucune résistance à la lame de coupe."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"De combien d’heures l’autonomie réelle est-elle inférieure à celle prévue par la simulation ?","aide":"Soustrais l’autonomie de l’essai à celle de la simulation.","type":"nombre","unite":"h"},{"enonce":"Associe chaque comparaison à l’écart qu’elle mesure.","aide":"Écart 1 : cahier des charges et modèle. Écart 2 : modèle et réel. Écart 3 : réel et cahier des charges.","type":"association","gauche":[{"id":"g0","texte":"2,6 h (simulation) comparée à 1,7 h (essai)"},{"id":"g1","texte":"1,7 h (essai) comparée à ≥ 2,0 h (cahier des charges)"},{"id":"g2","texte":"≥ 2,0 h (cahier des charges) comparée à 2,6 h (simulation)"}],"droite":[{"id":"d0","texte":"Écart 3"},{"id":"d1","texte":"Écart 1"},{"id":"d2","texte":"Écart 2"}]},{"enonce":"Touche, dans les notes, les deux mots qui désignent l’hypothèse du modèle contredite par le réel.","aide":"Les instruments, la batterie, le moteur et la pelouse sont hors de cause : cherche ce que la simulation supposait.","type":"zone","document":"notes","multiple":true},{"enonce":"Après correction de l’hypothèse, le modèle prévoit 1,7 h comme l’essai. Que conclure ?","aide":"Distingue l’écart modèle/réel (qui se ferme) de l’écart réel/cahier des charges (qui reste).","type":"choix","options":[{"id":"a","texte":"Le produit devient conforme puisque modèle et réel s’accordent désormais"},{"id":"b","texte":"Le cahier des charges est faux puisque le réel lui est inférieur"},{"id":"c","texte":"L’essai est invalide car il contredit la simulation initiale"},{"id":"d","texte":"Le modèle colle au réel, mais le produit reste non conforme : il faut revoir sa conception"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.9,"tolerance":0},"affichage":"0,9 h","explication":"2,6 − 1,7 = **0,9 h** : c’est l’écart entre le modèle et le réel."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Écart 1 : cahier des charges ↔ modèle. Écart 2 : modèle ↔ réel. Écart 3 : réel ↔ cahier des charges. Ici les écarts 1 et 2 sont réalisés avec la même simulation et l’écart 3 révèle un produit non conforme."},{"cle":{"type":"zone","ids":["m43","m44"]},"explication":"Le modèle supposait que l’herbe n’opposait **aucune résistance** : hypothèse trop grossière, qui explique les 0,9 h manquantes."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’écart 2 est refermé, mais 1,7 h < 2,0 h : l’écart 3 demeure. Le modèle est maintenant fiable ; c’est le **produit** qu’il faut améliorer."}]$ex$::jsonb),
  ('0ac4ea59-e43f-56e9-b998-771c3128048b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une imprimante 3D pour l’atelier","competence":"analyser-document","situation":"Le lycée veut offrir une imprimante 3D à l’atelier de technologie. Le professeur résume la demande de l’établissement ; Inès doit en tirer les contraintes du projet.","documents":[{"id":"note","type":"texte","genre":"article","titre":"Note de service","blocs":["Le lycée offre une imprimante 3D à l’atelier de technologie.","Le budget voté est de 1 200 €.","L’imprimante doit être installée avant les vacances de Noël.","Elle doit fabriquer des pièces de 20 cm de côté avec une précision de 0,2 mm."],"source":"Texte écrit pour l’exercice"},{"id":"phases","type":"chaine","disposition":"ligne","titre":"Les quatre phases du projet","noeuds":[{"id":"z1","texte":"Conception"},{"id":"z2","texte":"Planification"},{"id":"z3","texte":"Réalisation"},{"id":"z4","texte":"Terminaison"}],"liens":[{"de":"z1","a":"z2","texte":"jalon"},{"de":"z2","a":"z3","texte":"jalon"},{"de":"z3","a":"z4","texte":"jalon"}]}],"questions":[{"enonce":"Associe chaque phrase de la note à la contrainte du triangle du projet qu’elle exprime.","aide":"Coût : l’argent. Délai : le temps. Qualité : ce que le produit doit faire.","type":"association","gauche":[{"id":"g0","texte":"Budget de 1 200 €"},{"id":"g1","texte":"Installation avant Noël"},{"id":"g2","texte":"Pièces de 20 cm, précision 0,2 mm"}],"droite":[{"id":"d0","texte":"Délai"},{"id":"d1","texte":"Qualité"},{"id":"d2","texte":"Coût"}]},{"enonce":"Complète la phrase avec la bonne contrainte du triangle.","aide":"On ne peut pas améliorer une contrainte sans peser sur les deux autres : ici le budget et le délai sont fixés.","type":"trous","segments":["Pour installer l’imprimante plus tôt sans dépasser 1 200 €, il faudra accepter une moindre ",0,"."],"banque":["jalon","délai","coût","qualité"]},{"enonce":"Touche la phase qui s’achève par la livraison et le retour d’expérience.","aide":"C’est la dernière phase du cycle de vie du projet.","type":"zone","document":"phases","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Le budget est une contrainte de **coût**, la date de Noël une contrainte de **délai**, la taille et la précision des pièces la **qualité** attendue."},{"cle":{"type":"trous","trous":[["qualite"]]},"affichage":"qualité","explication":"Réduire le délai à budget constant se paie en **qualité** : c’est la règle du triangle du projet."},{"cle":{"type":"zone","ids":["z4"]},"explication":"La **terminaison** livre le produit, remet la documentation et tire le bilan. Chaque phase se clôt par un jalon."}]$ex$::jsonb),
  ('0ac4ea59-e43f-56e9-b998-771c3128048b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les bonnes exigences du store motorisé","competence":"analyser-document","situation":"Maëlys et son équipe rédigent le cahier des charges d’un store motorisé pour le CDI. Leur premier jet mélange des exigences bien formulées et d’autres qui ne le sont pas.","documents":[{"id":"brouillon","type":"tableau","titre":"Premier jet de l’équipe","colonnes":["Réf.","Exigence proposée"],"lignes":[["A","Être solide"],["B","Résister à un vent de 60 km/h (± 10 %)"],["C","Utiliser un moteur pas à pas"],["D","Se déployer en 20 s (± 2 s)"],["E","Être beau"]],"source":"Document imaginé pour l’exercice"}],"questions":[{"enonce":"Touche les deux exigences exploitables, c’est-à-dire dotées d’un critère, d’un niveau et d’une flexibilité.","aide":"Une exigence exploitable contient un nombre, une unité et une tolérance.","type":"zone","document":"brouillon","multiple":true},{"enonce":"Touche l’exigence qui impose une solution technique au lieu de dire ce que le store doit faire.","aide":"Un cahier des charges dit ce qu’il faut faire, jamais comment.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Classe ces fonctions du store.","aide":"Une contrainte est une limite imposée par le milieu extérieur : norme, température, coût, encombrement.","type":"categories","categories":[{"id":"c0","texte":"Fonction principale"},{"id":"c1","texte":"Fonction contrainte"}],"items":[{"id":"i0","texte":"Respecter la norme électrique en vigueur"},{"id":"i1","texte":"Coûter moins de 400 €"},{"id":"i2","texte":"Fonctionner entre − 10 °C et 50 °C"},{"id":"i3","texte":"Limiter l’éblouissement des occupants"},{"id":"i4","texte":"Protéger la pièce du soleil"}]},{"enonce":"Quelle est la durée de déploiement maximale acceptée pour l’exigence D ?","aide":"Niveau + flexibilité.","type":"nombre","unite":"s"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1","r3c1"]},"explication":"Les exigences **B** (vent, 60 km/h, ± 10 %) et **D** (durée, 20 s, ± 2 s) sont vérifiables. « Solide » et « beau » ne le sont pas."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"« Utiliser un moteur pas à pas » est une **solution** : elle interdit d’avance toute autre piste. Une bonne exigence parlerait de couple ou de précision."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Protéger du soleil et limiter l’éblouissement sont ce qui **justifie** le store. Norme, plage de températures et budget sont des **limites imposées** de l’extérieur."},{"cle":{"type":"nombre","valeur":22,"tolerance":0},"affichage":"22 s","explication":"20 s + 2 s = **22 s** : au-delà, l’exigence n’est plus respectée."}]$ex$::jsonb),
  ('0ac4ea59-e43f-56e9-b998-771c3128048b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le calendrier du drone d’inspection","competence":"raisonner","situation":"Une équipe développe un drone d’inspection de toitures en 12 semaines. Le client demande soudain une livraison en 9 semaines, sans augmenter le budget. L’équipe doit mesurer ce que cela coûte.","documents":[{"id":"phases","type":"tableau","titre":"Les phases du projet","colonnes":["Phase","Début","Fin","Jalon de sortie"],"lignes":[["Conception","S1","S3","Solution retenue"],["Planification","S4","S4","Planning validé"],["Réalisation","S5","S10","Drone testé"],["Terminaison","S11","S12","Livraison et bilan"]],"enteteLignes":true,"source":"Projet imaginé pour l’exercice"},{"id":"journal","type":"tableau","titre":"Journal du projet","colonnes":["Semaine","Événement"],"lignes":[["S2","Comparaison de trois solutions de motorisation"],["S4","Ordonnancement des tâches validé"],["S10","Vol d’essai et mesure de l’autonomie"],["S12","Remise du drone et de sa notice au client"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque événement du journal à la phase du cycle de vie qui le contient.","aide":"Conception : comparer des solutions. Planification : ordonner les tâches. Réalisation : fabriquer et tester. Terminaison : livrer.","type":"association","gauche":[{"id":"g0","texte":"S2 : trois solutions comparées"},{"id":"g1","texte":"S4 : tâches ordonnancées"},{"id":"g2","texte":"S10 : vol d’essai"},{"id":"g3","texte":"S12 : remise au client"}],"droite":[{"id":"d0","texte":"Planification"},{"id":"d1","texte":"Réalisation"},{"id":"d2","texte":"Terminaison"},{"id":"d3","texte":"Conception"}]},{"enonce":"Touche la phase la plus longue du projet.","aide":"Compte les semaines entre le début et la fin de chaque phase.","type":"zone","document":"phases","multiple":false},{"enonce":"Quelle part de la durée totale de 12 semaines occupe la réalisation ? (en pourcentage)","aide":"Divise la durée de la réalisation par la durée totale.","type":"nombre","unite":"%"},{"enonce":"L’équipe ramène la réalisation de 6 à 4 semaines, sans toucher aux autres phases. Quelle est alors la durée totale ?","aide":"Retranche les semaines gagnées à la durée totale.","type":"nombre","unite":"semaines"},{"enonce":"Pour tenir 9 semaines, que doit accepter le client ?","aide":"Pense au triangle coût – délai – qualité : on ne peut pas en améliorer une sans peser sur les autres.","type":"choix","options":[{"id":"a","texte":"Seule la qualité peut être réduite, jamais les deux autres contraintes"},{"id":"b","texte":"Rien à sacrifier : travailler plus vite suffit sans conséquence"},{"id":"c","texte":"Le coût baissera tout seul quand le délai sera plus court"},{"id":"d","texte":"Réduire le périmètre (par exemple un capteur en moins) ou augmenter le budget"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Comparer des solutions relève de la **conception**, ordonner les tâches de la **planification**, tester le drone de la **réalisation**, remettre le produit de la **terminaison**."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"La **réalisation** dure de S5 à S10 compris : 6 semaines, contre 3, 1 et 2 pour les autres."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 %","explication":"6 semaines sur 12 : 6 / 12 = **50 %** du projet."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 semaines","explication":"12 − (6 − 4) = **10 semaines** : c’est encore plus long que les 9 semaines demandées par le client."},{"cle":{"type":"choix","ids":["d"]},"explication":"Raccourcir un projet à budget constant se paie en **périmètre ou en qualité** ; garder tout en moins de temps coûte plus cher. Le triangle ne se triche pas."}]$ex$::jsonb),
  ('fcae5443-73a8-5c02-a69d-66f1a3e8378c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le moteur du vélo électrique sur le banc d’essai","competence":"calculer","situation":"Sur le banc d’essai du lycée, Karim fait tourner le moteur d’un vélo à assistance électrique. Un voltmètre et un ampèremètre donnent la puissance qu’il absorbe ; la fiche du moteur donne celle qu’il fournit.","documents":[{"id":"circ","type":"circuit","titre":"Montage du banc d’essai","branches":[{"de":[0,6],"a":[0,0],"composant":"pile"},{"de":[0,0],"a":[3,0]},{"de":[3,0],"a":[6,0],"composant":"amperemetre","nom":"A","id":"z1"},{"de":[6,0],"a":[8,0]},{"de":[8,0],"a":[12,0]},{"de":[8,0],"a":[8,6],"composant":"moteur","id":"z2"},{"de":[12,0],"a":[12,6],"composant":"voltmetre","nom":"V","id":"z3"},{"de":[12,6],"a":[8,6]},{"de":[8,6],"a":[5,6],"composant":"interrupteur-ferme","id":"z4"},{"de":[5,6],"a":[0,6]}]},{"id":"rel","type":"tableau","titre":"Relevés et fiche du moteur","colonnes":["Grandeur","Valeur"],"lignes":[["Tension aux bornes du moteur","36 V"],["Courant dans le moteur","8,0 A"],["Puissance mécanique fournie","250 W"]],"enteteLignes":true,"source":"Mesures arrondies, imaginées pour l’exercice"}],"questions":[{"enonce":"Touche l’appareil qui mesure le courant dans le moteur.","aide":"L’ampèremètre se place en série, sur le même fil que le moteur.","type":"zone","document":"circ","multiple":false},{"enonce":"Calcule la puissance électrique absorbée par le moteur.","aide":"En électricité, P = U × I.","type":"nombre","unite":"W"},{"enonce":"Calcule le rendement du moteur, arrondi au centième.","aide":"Rendement = puissance utile divisée par puissance absorbée.","type":"nombre"},{"enonce":"Où passent les 288 − 250 = 38 W manquants ?","aide":"Un rendement est toujours inférieur à 1 : que deviennent les pertes ?","type":"choix","options":[{"id":"a","texte":"38 W deviennent de la puissance mécanique supplémentaire"},{"id":"b","texte":"38 W partent en chaleur (effet Joule) et en frottements"},{"id":"c","texte":"Rien ne se perd : l’écart vient d’une erreur de mesure"},{"id":"d","texte":"38 W sont stockés dans la batterie pour plus tard"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"L’**ampèremètre** (A) est en série avec le moteur et mesure le courant. Le voltmètre (V), en dérivation, mesure la tension."},{"cle":{"type":"nombre","valeur":288,"tolerance":0},"affichage":"288 W","explication":"P = U × I = 36 × 8,0 = **288 W** absorbés."},{"cle":{"type":"nombre","valeur":0.87,"tolerance":0.003},"affichage":"0,87","explication":"η = 250 / 288 ≈ **0,87** : le moteur convertit 87 % de la puissance électrique en puissance mécanique."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les **pertes** partent en chaleur (effet Joule), en frottements et en bruit : la puissance utile reste toujours inférieure à la puissance absorbée."}]$ex$::jsonb),
  ('fcae5443-73a8-5c02-a69d-66f1a3e8378c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du moteur à la roue, des pertes en cascade","competence":"calculer","situation":"Sur un vélo électrique, Zoé veut 200 W à la roue. Entre la batterie et la roue, trois éléments se suivent et chacun perd un peu de puissance. Elle cherche ce que la batterie doit réellement fournir.","documents":[{"id":"cascade","type":"chaine","disposition":"ligne","titre":"Chaîne de puissance du vélo","noeuds":[{"id":"z1","texte":"Batterie"},{"id":"z2","texte":"Contrôleur η = 0,95"},{"id":"z3","texte":"Moteur η = 0,85"},{"id":"z4","texte":"Réducteur η = 0,90"},{"id":"z5","texte":"Roue : 200 W"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}],"source":"Rendements arrondis, imaginés pour l’exercice"}],"questions":[{"enonce":"Quel est le rendement global de la chaîne, arrondi au centième ?","aide":"En cascade, les rendements se multiplient.","type":"nombre"},{"enonce":"Quelle puissance la batterie doit-elle fournir pour obtenir 200 W à la roue ? Arrondis à l’unité.","aide":"Puissance utile = rendement global × puissance absorbée.","type":"nombre","unite":"W"},{"enonce":"Le vélo roule 30 minutes à cette puissance. Quelle énergie la batterie fournit-elle, en wattheures, arrondie à l’unité ?","aide":"E = P × t, avec t exprimé en heures (30 min = 0,5 h).","type":"nombre","unite":"Wh"},{"enonce":"Touche l’élément qui perd le plus de puissance dans la chaîne.","aide":"Le rendement le plus faible correspond aux pertes les plus fortes.","type":"zone","document":"cascade","multiple":false}]}$ex$::jsonb,
