  ('99195b56-a49b-5dcd-a801-5adaabd3ec2e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un brainstorming pour le robot tondeuse","competence":"analyser-document","situation":"Lina, Malik et Sam cherchent des idées pour un robot tondeuse. La séance dérape un peu : le professeur relit leurs échanges et leurs notes pour rappeler les règles de la conception.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Le fil de discussion de l’équipe","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"🧑","cote":"droite"},{"nom":"Sam","emoji":"👦","cote":"gauche"}],"repliques":[{"qui":"Lina","texte":"Idée : des panneaux solaires sur le capot pour recharger la tondeuse !"},{"qui":"Malik","texte":"Ou une lame qui se règle toute seule avec un capteur d’herbe."},{"qui":"Sam","texte":"Pff, c’est nul : trop cher, ça ne marchera jamais."},{"qui":"Lina","texte":"On note tout pour l’instant, on triera après."}],"source":"Échange écrit pour l’exercice"},{"id":"notes","type":"tableau","titre":"Notes en vrac de l’équipe","colonnes":["Ce qu’on a noté"],"lignes":[["Tondre la pelouse sans intervention de l’utilisateur"],["Rentrer seule à sa base quand la batterie est faible"],["Convertir l’énergie électrique en rotation de la lame"],["Mesurer le niveau de la batterie"],["Moteur brushless de 150 W"],["Capteur à ultrasons HC-SR04"]],"source":"Notes écrites pour l’exercice"}],"questions":[{"enonce":"Touche le mot par lequel Sam juge une idée alors que l’équipe cherche encore des idées.","aide":"Pendant la phase de recherche d’idées, il est interdit de juger.","type":"zone","document":"sms","multiple":false},{"enonce":"Complète la règle des deux temps de la recherche de solutions.","aide":"Le premier temps ouvre le choix, le second le referme.","type":"trous","segments":["Pendant la ",0,", on produit un maximum d’idées sans juger ; pendant la ",1,", on évalue et on retient."],"banque":["divergence","maquette","convergence","simulation"]},{"enonce":"Range chaque note du tableau dans le bon niveau, du besoin à la pièce choisie.","aide":"Service : ce que reçoit l’utilisateur. Technique : comment le système s’y prend. Solution : la pièce ou le composant.","type":"categories","categories":[{"id":"c0","texte":"Fonction de service"},{"id":"c1","texte":"Fonction technique"},{"id":"c2","texte":"Solution constructive"}],"items":[{"id":"i0","texte":"Mesurer le niveau de la batterie"},{"id":"i1","texte":"Moteur brushless de 150 W"},{"id":"i2","texte":"Capteur à ultrasons HC-SR04"},{"id":"i3","texte":"Tondre la pelouse sans intervention de l’utilisateur"},{"id":"i4","texte":"Convertir l’énergie électrique en rotation de la lame"},{"id":"i5","texte":"Rentrer seule à sa base quand la batterie est faible"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Le mot « **nul** » est un jugement. Pendant la divergence, juger tue les idées fragiles, dont sortent souvent les meilleures solutions."},{"cle":{"type":"trous","trous":[["divergence"],["convergence"]]},"affichage":"divergence · convergence","explication":"La **divergence** produit des idées, la **convergence** les évalue et en retient ; il est interdit de rouvrir la liste en convergence."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c2","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Une fonction de **service** parle à l’utilisateur ; une fonction **technique** décrit ce que fait le système en interne ; une **solution constructive** est le composant retenu, avec sa référence."}]$ex$::jsonb),
  ('99195b56-a49b-5dcd-a801-5adaabd3ec2e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Choisir le moteur de coupe avec un tableau multicritère","competence":"raisonner","situation":"L’équipe du robot tondeuse hésite entre trois moteurs pour la lame. Elle les compare avec un tableau multicritère : chaque critère reçoit un poids, chaque solution une note sur 5.","documents":[{"id":"tab","type":"tableau","titre":"Notes sur 5 des trois solutions","colonnes":["Critère","Poids","A : courant continu","B : brushless","C : pas à pas"],"lignes":[["Coût",3,5,2,3],["Bruit",2,2,4,3],["Rendement",3,3,5,2],["Fiabilité",2,3,5,4]],"enteteLignes":true,"source":"Notes imaginées pour l’exercice"},{"id":"poids2","type":"tableau","titre":"Poids proposés par le directeur, qui veut surtout un prix bas","colonnes":["Critère","Poids"],"lignes":[["Coût",5],["Bruit",1],["Rendement",2],["Fiabilité",2]],"enteteLignes":true}],"questions":[{"enonce":"Avec les poids du premier tableau, quel est le total pondéré de la solution B (brushless) ?","aide":"Multiplie chaque note de la colonne B par le poids de sa ligne, puis additionne.","type":"nombre"},{"enonce":"Avec les poids du directeur, quel est le total pondéré de la solution A (courant continu) ?","aide":"Reprends les notes de la colonne A et utilise les nouveaux poids 5, 1, 2 et 2.","type":"nombre"},{"enonce":"Avec les poids du directeur, range les solutions de la mieux classée à la moins bien classée.","aide":"Il te reste à calculer B et C avec les nouveaux poids (A vaut 39).","type":"ordre","items":[{"id":"a","texte":"B : brushless"},{"id":"b","texte":"C : pas à pas"},{"id":"c","texte":"A : courant continu"}]},{"enonce":"Le classement a changé avec les poids. Que montre cet exercice ?","aide":"Le tableau est un outil de discussion, pas un oracle.","type":"choix","options":[{"id":"a","texte":"Un tableau multicritère désigne la solution objectivement optimale"},{"id":"b","texte":"Le directeur a raison puisque son classement est le dernier calculé"},{"id":"c","texte":"Le tableau rend le choix explicite et discutable : changer les poids peut changer le classement"},{"id":"d","texte":"Le tableau a donné un résultat faux la première fois et un résultat juste la seconde fois"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":39,"tolerance":0},"affichage":"39","explication":"B : 3 × 2 + 2 × 4 + 3 × 5 + 2 × 5 = 6 + 8 + 15 + 10 = **39**. Avec ces poids, A obtient 34 et C 29."},{"cle":{"type":"nombre","valeur":39,"tolerance":0},"affichage":"39","explication":"A : 5 × 5 + 1 × 2 + 2 × 3 + 2 × 3 = 25 + 2 + 6 + 6 = **39**."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"Avec les nouveaux poids : A = 39, B = 5 × 2 + 1 × 4 + 2 × 5 + 2 × 5 = 34, C = 15 + 3 + 4 + 8 = 30. Le classement devient **A, B, C**, alors qu’il était B, A, C."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un tableau multicritère n’est pas un oracle : il met les **priorités à plat**. Savoir montrer que le classement dépend des poids fait partie du travail de l’ingénieur."}]$ex$::jsonb),
  ('99195b56-a49b-5dcd-a801-5adaabd3ec2e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le moteur du bras de robot chauffe trop","competence":"lire-graphique","situation":"Le moteur d’un bras de robot ne doit jamais dépasser 70 °C. Avant fabrication, l’équipe l’a simulé ; puis un prototype a été mesuré au banc. Les deux courbes ne racontent pas la même chose.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Température du moteur au cours d’un essai","categories":["0","5","10","15","20","25"],"series":[{"nom":"Simulation","valeurs":[20,35,45,52,57,60],"teinte":"bleu"},{"nom":"Mesure sur le prototype","valeurs":[20,40,54,64,71,75],"teinte":"corail"}],"axeY":{"titre":"Température","unite":"°C","min":0,"max":80,"pas":10},"axeX":{"titre":"Temps (min)"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"},{"id":"hyp","type":"texte","genre":"consigne","titre":"Hypothèses du modèle de simulation","blocs":["H1 : les pièces du bras sont indéformables.","H2 : les frottements dans les paliers sont négligés.","H3 : la tension d’alimentation reste constante."],"source":"Hypothèses écrites pour l’exercice"}],"questions":[{"enonce":"Quelle température la simulation prévoit-elle au bout de 20 minutes ?","aide":"Lis la courbe de la simulation à l’abscisse 20.","type":"nombre","unite":"°C"},{"enonce":"À 20 minutes, de combien de degrés la mesure dépasse-t-elle la simulation ?","aide":"Lis aussi la mesure à 20 minutes (71 °C), puis soustrais.","type":"nombre","unite":"°C"},{"enonce":"Touche l’instant où la mesure dépasse pour la première fois la limite de 70 °C.","aide":"Repère le premier point de la courbe de mesure situé au-dessus de la graduation 70.","type":"zone","document":"courbe","multiple":false},{"enonce":"Touche le mot de l’hypothèse qui explique le mieux que la simulation sous-estime la chaleur.","aide":"Qu’est-ce qui produit de la chaleur dans un moteur mécanique, en plus du courant ?","type":"zone","document":"hyp","multiple":false},{"enonce":"Peut-on valider l’exigence « moteur sous 70 °C » avec la seule simulation ?","aide":"Un résultat de simulation n’a de sens que dans le cadre de ses hypothèses.","type":"choix","options":[{"id":"a","texte":"Oui : la simulation est un résultat de calcul, donc plus fiable que la mesure"},{"id":"b","texte":"Non : la simulation sous-estime l’échauffement, il faut affiner le modèle ou valider par l’essai"},{"id":"c","texte":"Non : mais seulement parce qu’il manque un point à 30 minutes"},{"id":"d","texte":"Oui : 60 °C à 25 minutes prouve que le moteur reste sous 70 °C"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":57,"tolerance":1},"affichage":"57 °C","explication":"À 20 minutes, la simulation prévoit **57 °C**, sous la limite de 70 °C."},{"cle":{"type":"nombre","valeur":14,"tolerance":1},"affichage":"14 °C","explication":"71 − 57 = **14 °C** d’écart : la simulation sous-estime l’échauffement."},{"cle":{"type":"zone","ids":["k4"]},"explication":"À **20 minutes**, la mesure atteint 71 °C ; à 15 minutes elle n’était qu’à 64 °C. L’exigence des 70 °C n’est pas tenue."},{"cle":{"type":"zone","ids":["m9"]},"explication":"Les **frottements** des paliers produisent de la chaleur : les négliger donne un moteur trop « froid » dans la simulation."},{"cle":{"type":"choix","ids":["b"]},"explication":"Une simulation n’a de valeur que dans le cadre de ses **hypothèses simplificatrices** ; ici l’une est fausse, et la mesure le prouve. Il faut corriger le modèle ou valider sur le prototype."}]$ex$::jsonb),
  ('0fca8277-b3e5-5e39-828e-86b8e3fb88ce'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les capteurs du portail automatique","competence":"lire-tableau","situation":"Le portail du lycée surveille sa position, la présence d’un obstacle et la température de son moteur. Rayan range ses capteurs : chacun délivre un signal d’un type différent.","documents":[{"id":"capteurs","type":"tableau","titre":"Les capteurs du portail","colonnes":["Capteur","Grandeur mesurée","Signal de sortie"],"lignes":[["Fin de course","Position du vantail","0 ou 1"],["Cellule","Présence d’un obstacle","0 ou 1"],["Sonde de température","Température du moteur","Tension continue de 0 à 3,3 V"],["Codeur magnétique","Angle de l’arbre","Valeur codée envoyée sur un bus I2C"]],"enteteLignes":true,"source":"Système imaginé pour l’exercice"}],"questions":[{"enonce":"Touche la case qui décrit un signal analogique.","aide":"Un signal analogique est une tension qui varie de façon continue avec la grandeur mesurée.","type":"zone","document":"capteurs","multiple":false},{"enonce":"Classe chaque capteur selon la nature de son signal.","aide":"TOR : deux états seulement. Analogique : tension continue. Numérique : valeur codée sur un bus.","type":"categories","categories":[{"id":"c0","texte":"TOR"},{"id":"c1","texte":"Analogique"},{"id":"c2","texte":"Numérique"}],"items":[{"id":"i0","texte":"Sonde de température"},{"id":"i1","texte":"Cellule"},{"id":"i2","texte":"Fin de course"},{"id":"i3","texte":"Codeur magnétique"}]},{"enonce":"Un CAN de 10 bits lit la tension de la sonde. Combien de valeurs différentes peut-il produire ?","aide":"Avec n bits, on obtient 2 puissance n niveaux.","type":"nombre"},{"enonce":"Le CAN de 10 bits couvre de 0 à 3,3 V. Quel est le pas de quantification, en millivolts, arrondi au centième ?","aide":"Divise la pleine échelle (3 300 mV) par le nombre de niveaux.","type":"nombre","unite":"mV"}]}$ex$::jsonb,
