   $ex${"titre":"Le cerveau du portail : états et boucle","competence":"modeliser","situation":"Un portail coulissant est commandé par un microcontrôleur qui répète sans fin la même boucle toutes les 20 ms. Mehdi doit lire son diagramme d’états, son programme et ses caractéristiques pour chiffrer le fonctionnement.","documents":[{"id":"etats","type":"schema","titre":"Diagramme d’états du portail","largeur":420,"hauteur":245,"elements":[{"forme":"rect","x":10,"y":105,"l":100,"h":44,"arrondi":10,"texte":"Fermé","teinte":"violet","motif":"clair"},{"forme":"rect","x":160,"y":25,"l":120,"h":44,"arrondi":10,"texte":"En ouverture","teinte":"violet","motif":"clair"},{"forme":"rect","x":310,"y":105,"l":100,"h":44,"arrondi":10,"texte":"Ouvert","teinte":"violet","motif":"clair"},{"forme":"rect","x":160,"y":185,"l":120,"h":44,"arrondi":10,"texte":"En fermeture","teinte":"violet","motif":"clair"},{"forme":"ligne","de":[70,105],"a":[160,55],"fleche":"fin","teinte":"encre"},{"forme":"texte","x":14,"y":78,"texte":"télécommande","taille":"petit","ancre":"debut","id":"z1","zone":true},{"forme":"ligne","de":[280,52],"a":[350,105],"fleche":"fin","teinte":"encre"},{"forme":"texte","x":292,"y":36,"texte":"fin de course ouvert","taille":"petit","ancre":"debut","id":"z2","zone":true},{"forme":"ligne","de":[350,149],"a":[280,200],"fleche":"fin","teinte":"encre"},{"forme":"texte","x":322,"y":190,"texte":"après 30 s","taille":"petit","ancre":"debut","id":"z3","zone":true},{"forme":"ligne","de":[160,200],"a":[70,149],"fleche":"fin","teinte":"encre"},{"forme":"texte","x":10,"y":224,"texte":"fin de course fermé","taille":"petit","ancre":"debut","id":"z4","zone":true},{"forme":"ligne","de":[220,185],"a":[220,69],"fleche":"fin","teinte":"encre"},{"forme":"texte","x":230,"y":130,"texte":"obstacle","taille":"petit","ancre":"debut","id":"z5","zone":true}]},{"id":"prog","type":"texte","genre":"consigne","titre":"Programme principal","blocs":["répéter indéfiniment :","    lire bouton, obstacle, fin_ouvert, fin_ferme","    si état = FERMÉ et bouton = 1 : état ← OUVERTURE","    si état = OUVERTURE et fin_ouvert = 1 : état ← OUVERT","    si état = FERMETURE et obstacle = 1 : état ← …","    écrire le moteur selon l’état"],"source":"Pseudo-code écrit pour l’exercice"},{"id":"data","type":"tableau","titre":"Caractéristiques","colonnes":["Grandeur","Valeur"],"lignes":[["Course du vantail","4,0 m"],["Vitesse du vantail","0,25 m/s"],["Période de la boucle","20 ms"]],"enteteLignes":true}],"questions":[{"enonce":"Le vantail se ferme et la cellule détecte un enfant. Touche la transition que le portail doit alors prendre.","aide":"Pars de l’état « En fermeture » et cherche la flèche déclenchée par un obstacle.","type":"zone","document":"etats","multiple":false},{"enonce":"Complète la ligne du programme qui contient « … », en t’aidant du diagramme.","aide":"Le programme doit réaliser la transition que tu viens de repérer sur le diagramme.","type":"trous","segments":["Dans l’état FERMETURE, si obstacle = 1, le programme met état ← ",0,"."],"banque":["OUVERTURE","FERMETURE","FERMÉ","OUVERT"]},{"enonce":"Combien de temps dure l’ouverture complète du portail ?","aide":"Durée = distance divisée par vitesse.","type":"nombre","unite":"s"},{"enonce":"Combien de fois la boucle du programme s’exécute-t-elle pendant cette ouverture ?","aide":"Convertis 20 ms en secondes, puis divise la durée de l’ouverture par la période de la boucle.","type":"nombre"}]}$ex$::jsonb,
