  ('87cc1792-39e8-5d7c-ba06-3ee7e2747ad2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le réseau PERT du store motorisé","competence":"calculer","situation":"Un groupe de lycéens fabrique un store motorisé pour le CDI. Six tâches, des durées, des antériorités : Zoé calcule les dates au plus tôt pour trouver ce qui commande la durée du projet.","documents":[{"id":"taches","type":"tableau","titre":"Les tâches du projet","colonnes":["Tâche","Description","Durée (jours)","Antériorités"],"lignes":[["A","Étude du besoin",2,"aucune"],["B","Conception mécanique",4,"A"],["C","Conception électronique",3,"A"],["D","Fabrication des pièces",5,"B et C"],["E","Programmation",2,"C"],["F","Assemblage et essais",3,"D et E"]],"enteteLignes":true,"source":"Projet imaginé pour l’exercice"}],"questions":[{"enonce":"Au bout de combien de jours la tâche D peut-elle commencer au plus tôt ?","aide":"D attend B et C : calcule la fin de chacune et prends la plus tardive.","type":"nombre","unite":"jours"},{"enonce":"Touche les quatre tâches du chemin critique.","aide":"Cherche la suite de tâches qui, mise bout à bout, donne la durée totale la plus longue.","type":"zone","document":"taches","multiple":true},{"enonce":"Quelle est la durée minimale du projet ?","aide":"C’est la longueur du chemin critique.","type":"nombre","unite":"jours"},{"enonce":"L’équipe parvient à programmer en 2 jours de moins (tâche E). Combien de jours le projet y gagne-t-il ?","aide":"Accélérer une tâche hors du chemin critique ne fait rien gagner.","type":"choix","options":[{"id":"a","texte":"Aucun jour : E a une marge de 4 jours et n’est pas sur le chemin critique"},{"id":"b","texte":"Deux jours : la durée de la tâche diminue, donc celle du projet aussi"},{"id":"c","texte":"Quatre jours : toute la marge de E est récupérée par le projet"},{"id":"d","texte":"Un jour : la moitié du temps gagné sur E profite au projet"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 jours","explication":"A finit à 2 j ; B finit à 2 + 4 = 6 j, C à 2 + 3 = 5 j. D commence donc au plus tôt à **6 jours**."},{"cle":{"type":"zone","ids":["r0c0","r1c0","r3c0","r5c0"]},"explication":"Le chemin critique est **A → B → D → F** : 2 + 4 + 5 + 3 = 14 jours. C (marge 1 jour) et E (marge 4 jours) peuvent glisser sans retarder le projet."},{"cle":{"type":"nombre","valeur":14,"tolerance":0},"affichage":"14 jours","explication":"La durée minimale est la longueur du chemin critique : **14 jours**."},{"cle":{"type":"choix","ids":["a"]},"explication":"E a une marge de 4 jours : l’accélérer ne change pas le chemin critique A → B → D → F. Le projet y gagne **0 jour** ; on ne renforce que ce qui est critique."}]$ex$::jsonb),
  ('87cc1792-39e8-5d7c-ba06-3ee7e2747ad2'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La panne d’imprimante retarde le drone","competence":"raisonner","situation":"Une équipe de lycéens assemble un drone d’inspection. Au jour 4, l’imprimante 3D tombe en panne : une tâche va durer plus longtemps. Le chef de projet doit savoir si le projet prend du retard, et que faire.","documents":[{"id":"taches","type":"tableau","titre":"Les tâches du projet","colonnes":["Tâche","Description","Durée (jours)","Antériorités"],"lignes":[["A","Commande des composants",3,"aucune"],["B","Impression 3D du châssis",4,"aucune"],["C","Soudure de la carte de puissance",2,"A"],["D","Assemblage mécanique",2,"A et B"],["E","Câblage et réglages",3,"C et D"],["F","Essais en vol",2,"E"]],"enteteLignes":true,"source":"Projet imaginé pour l’exercice"},{"id":"journal","type":"texte","genre":"article","titre":"Journal du chef de projet","blocs":["Jour 4 : l’imprimante du lycée tombe en panne. L’impression du châssis (B) durera 6 jours au lieu de 4.","Une seconde imprimante existe dans un autre établissement, à trois quarts d’heure de route."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Avant la panne, touche les quatre tâches du chemin critique.","aide":"Compare les chemins B → D → E → F, A → D → E → F et A → C → E → F.","type":"zone","document":"taches","multiple":true},{"enonce":"Quelle était la durée minimale prévue du projet ?","aide":"C’est la longueur du chemin critique.","type":"nombre","unite":"jours"},{"enonce":"Imaginons que la soudure C dure 3 jours au lieu de 2. Quel effet sur la durée du projet ?","aide":"Calcule la marge de C : l’écart entre sa date au plus tard et sa date au plus tôt.","type":"choix","options":[{"id":"a","texte":"Le projet avance d’un jour : un retard sur C libère le soudeur"},{"id":"b","texte":"Rien : la tâche C dispose d’une marge de 1 jour, qui absorbe le retard"},{"id":"c","texte":"Le projet recule d’un jour : le retard d’une tâche se reporte toujours"},{"id":"d","texte":"Le projet recule d’un jour, car C est sur le chemin critique"}],"multiple":false},{"enonce":"Avec la panne (B dure 6 jours), quelle est la nouvelle durée minimale du projet ?","aide":"Recalcule la longueur du chemin passant par B : 6 + 2 + 3 + 2.","type":"nombre","unite":"jours"},{"enonce":"Quelle décision permet de limiter le retard ?","aide":"Un retard sur une tâche critique impose d’agir sur cette tâche : ajouter des moyens, réduire le périmètre ou accepter le décalage.","type":"choix","options":[{"id":"a","texte":"Accélérer la soudure C pour compenser le retard"},{"id":"b","texte":"Raccourcir la commande A, puisqu’elle est au début du projet"},{"id":"c","texte":"Faire imprimer le châssis sur la seconde imprimante pour retrouver du temps sur B"},{"id":"d","texte":"Ne rien faire, la marge des tâches non critiques absorbera le retard"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r3c0","r4c0","r5c0"]},"explication":"B → D → E → F fait 4 + 2 + 3 + 2 = 11 jours, contre 10 pour les deux autres chemins : le chemin critique est **B, D, E, F**."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11 jours","explication":"4 + 2 + 3 + 2 = **11 jours**."},{"cle":{"type":"choix","ids":["b"]},"explication":"C finit au plus tôt à 5 j et peut finir au plus tard à 6 j (début de E) : sa marge est de 1 jour. Un retard de 1 jour **se résorbe**, le projet reste à 11 jours."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 jours","explication":"B → D → E → F fait désormais 6 + 2 + 3 + 2 = **13 jours** : le projet a 2 jours de retard."},{"cle":{"type":"choix","ids":["c"]},"explication":"B est critique : il faut lui **ajouter des moyens** (seconde imprimante). Accélérer C ou A ne gagne rien, et la marge n’existe pas sur le chemin critique."}]$ex$::jsonb),
  ('387fd060-82f1-59b8-9de2-8c207df43d5c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un robot tondeuse conforme… mais inadapté","competence":"analyser-document","situation":"Le robot tondeuse du lycée est livré à un jardinier. Au contrôle, il respecte toutes ses spécifications. Pourtant, quelques jours plus tard, le client écrit une lettre mécontente.","documents":[{"id":"recette","type":"tableau","titre":"Recette : spécifications et mesures","colonnes":["Exigence","Niveau demandé","Mesuré"],"lignes":[["Hauteur de coupe","4 cm ± 0,5 cm","4,2 cm"],["Autonomie","≥ 90 min","95 min"],["Pente franchissable","≥ 15°","15°"]],"enteteLignes":true,"source":"Mesures imaginées pour l’exercice"},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre du client","blocs":["Madame, Monsieur,","Mon jardin descend vers la rivière avec une pente de 25°. Votre robot patine dès les premiers mètres et ne tond presque rien.","Je voulais une machine qui tonde tout mon terrain."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Combien d’exigences du tableau sont respectées par le robot ?","aide":"Compare chaque mesure au niveau demandé, en tenant compte de la flexibilité.","type":"nombre"},{"enonce":"Touche, dans la lettre, la donnée qui montre que la spécification traduisait mal le besoin du client.","aide":"Cherche une valeur chiffrée qui dépasse ce que le robot sait franchir.","type":"zone","document":"lettre","multiple":false},{"enonce":"Que peut-on dire du robot ?","aide":"Vérifier : a-t-on bien construit le produit ? Valider : a-t-on construit le bon produit ?","type":"choix","options":[{"id":"a","texte":"Il est vérifié, car conforme aux spécifications, mais pas validé, car il ne répond pas au besoin réel"},{"id":"b","texte":"Il n’est ni vérifié ni validé, puisqu’un client est mécontent"},{"id":"c","texte":"Il est à la fois vérifié et validé, puisque toutes les mesures sont bonnes"},{"id":"d","texte":"Il est validé, car conforme aux spécifications, et pas vérifié, car le client se plaint"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"Coupe : 4,2 cm est dans 4 ± 0,5 cm. Autonomie : 95 ≥ 90. Pente : 15° ≥ 15°. Les **trois** exigences sont respectées : le robot est conforme à ses spécifications."},{"cle":{"type":"zone","ids":["m12"]},"explication":"La pente de **25°** du jardin dépasse les 15° de la spécification : le robot est conforme à la spécification, mais celle-ci traduisait mal le besoin réel."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Vérifier**, c’est comparer aux spécifications ; **valider**, c’est confronter au besoin réel. Un produit peut être parfaitement vérifié et rester invalide."}]$ex$::jsonb),
  ('387fd060-82f1-59b8-9de2-8c207df43d5c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’imprimante 3D n’atteint pas sa vitesse","competence":"raisonner","situation":"Pendant la recette de l’imprimante 3D, Noémie constate que la vitesse d’impression n’atteint pas celle du cahier des charges. L’équipe doit comprendre l’origine de l’écart avant de modifier quoi que ce soit.","documents":[{"id":"vit","type":"tableau","titre":"Vitesse d’impression","colonnes":["Source","Vitesse"],"lignes":[["Cahier des charges","≥ 60 mm/s"],["Simulation","58 mm/s"],["Essai n° 1","48 mm/s"]],"enteteLignes":true,"source":"Mesures imaginées pour l’exercice"},{"id":"proto","type":"texte","genre":"article","titre":"Protocole de l’essai n° 1","blocs":["La vitesse a été relevée en chronométrant à la main le déplacement de la tête d’impression sur 5 secondes."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"De combien la vitesse mesurée est-elle inférieure à l’exigence du cahier des charges ?","aide":"Soustrais la vitesse de l’essai à celle du cahier des charges.","type":"nombre","unite":"mm/s"},{"enonce":"Quel pourcentage de l’exigence ces 12 mm/s représentent-ils ?","aide":"Divise l’écart par la vitesse du cahier des charges.","type":"nombre","unite":"%"},{"enonce":"Associe chaque constat à l’origine possible de l’écart qu’il explique.","aide":"Trois origines : une fabrication non conforme, une mesure mal faite, un modèle trop grossier.","type":"association","gauche":[{"id":"g0","texte":"La courroie de l’axe X patine sur sa poulie"},{"id":"g1","texte":"Le temps a été chronométré à la main sur 5 s"},{"id":"g2","texte":"Le modèle supposait des accélérations instantanées"}],"droite":[{"id":"d0","texte":"Le protocole de mesure"},{"id":"d1","texte":"Une hypothèse du modèle"},{"id":"d2","texte":"Le produit"}]},{"enonce":"L’équipe refait l’essai avec un capteur optique pendant 60 s et obtient 47 mm/s. Que conclure ?","aide":"Une mesure plus précise donne la même valeur qu’avant : le défaut ne venait pas de la mesure.","type":"choix","options":[{"id":"a","texte":"L’origine « protocole de mesure » est écartée : l’écart vient du produit ou du modèle"},{"id":"b","texte":"L’écart disparaît : la mesure précise confirme les 60 mm/s du cahier des charges"},{"id":"c","texte":"Le produit est validé, car deux mesures donnent presque la même valeur"},{"id":"d","texte":"Le modèle est confirmé : 47 mm/s s’approche des 58 mm/s simulés"}],"multiple":false}]}$ex$::jsonb,
