  ('387fd060-82f1-59b8-9de2-8c207df43d5c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le bras de robot a dérivé sans que personne ne le sache","competence":"raisonner","situation":"Un projet de bras de robot s’achève. Pendant la réalisation, plusieurs modifications ont été demandées. L’équipe prépare le bilan et doit savoir ce que le projet a réellement coûté, et ce qu’il faut en retenir.","documents":[{"id":"base","type":"tableau","titre":"Le projet au départ","colonnes":["Grandeur","Valeur prévue"],"lignes":[["Budget","5 000 €"],["Délai","30 jours"]],"enteteLignes":true,"source":"Projet imaginé pour l’exercice"},{"id":"modifs","type":"tableau","titre":"Journal des modifications","colonnes":["N°","Demande","Surcoût","Délai en plus","Statut"],"lignes":[["1","Pince à trois doigts","+ 450 €","+ 5 j","Chiffrée et validée"],["2","Capot d’une autre couleur","non chiffré","non chiffré","Acceptée oralement"],["3","Capteur de force en plus","+ 300 €","+ 2 j","Chiffrée et validée"]]}],"questions":[{"enonce":"Touche la case du statut de la modification qui ne respecte pas la règle « tracée, chiffrée et validée ».","aide":"Regarde comment chaque demande a été acceptée.","type":"zone","document":"modifs","multiple":false},{"enonce":"Quel est le budget total, en ajoutant les deux modifications chiffrées au budget initial ?","aide":"Additionne 5 000 € et les surcoûts des modifications 1 et 3.","type":"nombre","unite":"€"},{"enonce":"De quel pourcentage du budget initial le budget a-t-il augmenté ?","aide":"Divise l’augmentation totale par le budget initial.","type":"nombre","unite":"%"},{"enonce":"Range les étapes de la terminaison du projet dans leur ordre.","aide":"On livre d’abord, on clôt à la toute fin.","type":"ordre","items":[{"id":"a","texte":"Livraison et recette avec le client"},{"id":"b","texte":"Clôture : archivage et dissolution de l’équipe"},{"id":"c","texte":"Remise de la documentation"},{"id":"d","texte":"Bilan et retour d’expérience"}]},{"enonce":"À qui profite surtout le retour d’expérience ?","aide":"Le projet en cours est terminé.","type":"choix","options":[{"id":"a","texte":"À personne : la clôture a déjà dissous l’équipe"},{"id":"b","texte":"Au client, qui est remboursé du surcoût"},{"id":"c","texte":"Aux projets suivants, qui évitent de refaire les mêmes erreurs"},{"id":"d","texte":"Au projet en cours, qui peut encore corriger sa dérive de budget"}],"multiple":false}]}$ex$::jsonb,
