   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"L’exigence **1.1** (puissance mécanique ≥ 250 W) se vérifie à partir du couple et de la vitesse du moteur."},{"cle":{"type":"nombre","valeur":288,"tolerance":0},"affichage":"288 W","explication":"P = 36 × 8,0 = **288 W**."},{"cle":{"type":"nombre","valeur":251.3,"tolerance":0.06},"affichage":"251,3 W","explication":"ω = 300 × 2π / 60 ≈ 31,42 rad/s ; P = 8,0 × 31,42 ≈ **251,3 W**."},{"cle":{"type":"choix","ids":["d"]},"explication":"On compare 251,3 W au niveau 250 W : l’exigence est **respectée**, de justesse. Le rendement de 87 % (251,3 / 288) explique l’écart avec la puissance électrique."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Volts et ampères : énergie **électrique**. Newtons-mètres et tours par minute : énergie **mécanique**. Des impulsions comptées : de l’**information**."}]$ex$::jsonb),
  ('250fa736-d78b-5639-b6de-38df00e23d78'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vent pousse le drone","competence":"geometrie","situation":"Un drone est en O. Le vent exerce sur lui une force représentée par le vecteur OF ; sur le quadrillage, un carreau représente 1 newton. Léo décrit cette force avec les quatre caractéristiques d’un vecteur.","documents":[{"id":"fig","type":"figure","cadre":{"xmin":-1,"xmax":6,"ymin":-1,"ymax":5},"quadrillage":true,"points":[{"id":"O","x":0,"y":0,"position":"so"},{"id":"P","x":3,"y":0,"position":"se"},{"id":"F","x":3,"y":4,"position":"ne"}],"segments":[{"de":"O","a":"P"},{"de":"P","a":"F"},{"de":"O","a":"F","id":"z1"}],"angles":[{"sommet":"P","de":"O","a":"F","droit":true}],"titre":"Le vecteur OF","source":"Figure écrite pour l’exercice"}],"questions":[{"enonce":"Touche le point d’application de la force.","aide":"C’est le point où la force s’exerce : le drone est en O.","type":"zone","document":"fig","multiple":false},{"enonce":"Les coordonnées de OF sont (3 ; 4). Quelle est la norme de la force, en newtons ?","aide":"Dans le plan, la norme est la racine carrée de x² + y².","type":"nombre","unite":"N"},{"enonce":"Une bourrasque inverse exactement la force : le vecteur devient −OF. Que devient-il ?","aide":"Multiplier un vecteur par un réel négatif inverse son sens.","type":"choix","options":[{"id":"a","texte":"Même point d’application et même sens, mais norme 5 fois plus petite"},{"id":"b","texte":"Même direction et même norme, mais sens opposé : coordonnées (− 3 ; − 4)"},{"id":"c","texte":"Même direction et même sens, norme opposée : coordonnées (− 3 ; − 4)"},{"id":"d","texte":"Même sens, direction opposée et même norme : coordonnées (3 ; − 4)"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["O"]},"explication":"Le point d’application est **O** : la force s’exerce sur le drone. Les trois autres caractéristiques sont la direction, le sens et la norme."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 N","explication":"‖OF‖ = √(3² + 4²) = √25 = **5 N**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Multiplier par − 1 inverse le **sens** ; la direction et la norme (5 N) ne changent pas, et les coordonnées changent de signe : **(− 3 ; − 4)**."}]$ex$::jsonb),
  ('250fa736-d78b-5639-b6de-38df00e23d78'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le robot-livreur sur sa rampe","competence":"modeliser","situation":"Un robot-livreur de 12 kg monte une rampe d’accès inclinée à 20°. Pour savoir ce qui le fait glisser, Anaïs décompose son poids dans un repère lié à la rampe : un axe le long de la pente et un axe perpendiculaire.","documents":[{"id":"rampe","type":"schema","titre":"Le poids du robot sur la rampe","largeur":340,"hauteur":250,"elements":[{"forme":"polygone","points":[[30,175],[310,175],[310,73.1]],"teinte":"sable","motif":"clair"},{"forme":"polygone","points":[[139.9,135],[200.1,113.1],[189.2,83],[129,104.9]],"teinte":"violet","motif":"plein"},{"forme":"texte","x":152.9,"y":77.1,"texte":"robot","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[164.5,109],"a":[164.5,229],"fleche":"fin","teinte":"encre","epaisseur":3},{"forme":"texte","x":148.5,"y":233,"texte":"P","ancre":"debut","gras":true},{"forme":"ligne","de":[164.5,109],"a":[125.9,123],"fleche":"fin","teinte":"encre","epaisseur":3,"id":"z1","zone":true},{"forme":"ligne","de":[164.5,109],"a":[203.1,215],"fleche":"fin","teinte":"encre","epaisseur":3,"id":"z2","zone":true},{"forme":"chemin","d":"M 70 175 A 40 40 0 0 0 67.6 161.3","teinte":"encre"},{"forme":"texte","x":78,"y":169,"texte":"α = 20°","ancre":"debut","taille":"petit"}],"source":"Schéma simplifié écrit pour l’exercice"},{"id":"data","type":"tableau","titre":"Données","colonnes":["Grandeur","Valeur"],"lignes":[["Masse du robot","12 kg"],["Intensité de la pesanteur","9,81 N/kg"],["Inclinaison de la rampe","20°"],["Angle entre le poids et l’axe de la rampe","70°"]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est la norme du poids du robot ? Arrondis au dixième de newton.","aide":"P = m × g.","type":"nombre","unite":"N"},{"enonce":"Touche la composante du poids qui tend à faire descendre le robot le long de la rampe.","aide":"Elle est portée par la rampe elle-même, pas par la perpendiculaire.","type":"zone","document":"rampe","multiple":false},{"enonce":"Quelle est la norme de cette composante le long de la rampe ? Arrondis au dixième de newton.","aide":"La composante le long d’un axe fait intervenir le cosinus de l’angle avec cet axe : ici 70°.","type":"nombre","unite":"N"},{"enonce":"La rampe est relevée de 20° à 30°. Que devient la composante du poids le long de la rampe ?","aide":"Calcule l’angle entre le poids et l’axe de la rampe dans le nouveau cas, puis compare les cosinus.","type":"choix","options":[{"id":"a","texte":"Elle diminue : une pente plus forte retient mieux le robot sur la rampe et le stabilise"},{"id":"b","texte":"Elle augmente : l’angle du poids avec la rampe passe à 60° et son cosinus augmente"},{"id":"c","texte":"Elle reste la même : le poids du robot ne dépend pas de l’inclinaison de la rampe"},{"id":"d","texte":"Elle s’annule dès que la pente dépasse 25°, car le robot ne glisse plus du tout"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":117.7,"tolerance":0.06},"affichage":"117,7 N","explication":"P = 12 × 9,81 = 117,72 N, soit **117,7 N**."},{"cle":{"type":"zone","ids":["z1"]},"explication":"La composante **parallèle à la rampe** tire le robot vers le bas de la pente ; la composante perpendiculaire est équilibrée par la rampe."},{"cle":{"type":"nombre","valeur":40.3,"tolerance":0.06},"affichage":"40,3 N","explication":"P × cos 70° = 117,72 × 0,342 ≈ **40,3 N**. Si l’on avait pris le cosinus de 20°, on aurait trouvé 110,6 N : l’erreur classique."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’angle passe de 70° à 60°, donc cos 60° = 0,5 est plus grand que cos 70° ≈ 0,34 : la composante vaut alors **58,9 N**, elle augmente."}]$ex$::jsonb),
