   $ex${"titre":"Le robot tondeuse dans la pente","competence":"lire-tableau","situation":"Un robot tondeuse est à l’arrêt sur une pente. Le sol doit lui fournir une composante tangentielle de 36 N pour le retenir ; la composante normale du contact est de 90 N.","documents":[{"id":"terrains","type":"tableau","titre":"Coefficient de frottement des roues selon le terrain","source":"Valeurs imaginées pour l’exercice","enteteLignes":true,"colonnes":["Terrain","Coefficient f"],"lignes":[["Herbe sèche","0,6"],["Herbe mouillée","0,35"],["Gravier","0,5"]]}],"questions":[{"enonce":"Quelle composante tangentielle maximale le contact peut-il fournir sur herbe sèche ?","aide":"Sans glissement, T ≤ f × N, avec N = 90 N.","type":"nombre","unite":"N"},{"enonce":"Classe chaque terrain : le robot y reste-t-il immobile ou glisse-t-il ?","aide":"Compare 36 N à f × 90 pour chaque terrain.","type":"categories","categories":[{"id":"c0","texte":"Reste immobile"},{"id":"c1","texte":"Glisse"}],"items":[{"id":"i0","texte":"Herbe mouillée"},{"id":"i1","texte":"Herbe sèche"},{"id":"i2","texte":"Gravier"}]},{"enonce":"Quel coefficient de frottement minimal évite tout glissement, avec N = 90 N et T = 36 N ?","aide":"À la limite, T = f × N, donc f = T / N.","type":"nombre"}]}$ex$::jsonb,
