s":true}]}],"questions":[{"enonce":"En quel point écrire la somme des moments pour obtenir C sans autre inconnue ?","aide":"Choisis le point où passent le plus d’inconnues : leur moment y est nul.","type":"choix","options":[{"id":"a","texte":"En un point du sol"},{"id":"b","texte":"En G, au milieu du bras"},{"id":"c","texte":"En O, où passent X et Y"},{"id":"d","texte":"En A, où agit la charge"}],"multiple":false},{"enonce":"Écris la somme des moments en O et calcule le couple C de maintien.","aide":"C équilibre P × OG + Q × OA, avec OG = 0,25 m.","type":"nombre","unite":"N·m"},{"enonce":"Calcule la composante verticale Y de l’action du pivot.","aide":"Somme des forces sur y = 0 : Y compense P et Q.","type":"nombre","unite":"N"},{"enonce":"Le moteur est limité à 30 N·m. Quelle charge Q maximale le bras peut-il tenir ?","aide":"C = 5 + 0,5 × Q : résous 30 = 5 + 0,5 × Q.","type":"nombre","unite":"N"}]}$ex$::jsonb,
